module.exports = JSON.parse("{\"0\":{\"buttons\":[{\"name\":\"Let me have a look.\",\"type\":\"perform\"},{\"name\":\"I think I'll go instead...\"}],\"text\":\"Hello! My name is Ivan. I can help you with furniture in your home. With my assistance, you can either purchase furniture for dollars or craft it using resources. Interested?\",\"sound\":\"cloud/npc/furniture/furniture.ogg\"}}");

