module.exports = JSON.parse("{\"0\":{\"buttons\":[{\"name\":\"I want to get a driver's license\",\"questId\":1},{\"name\":\"I want to get an air transport license\",\"questId\":2},{\"name\":\"I want to get a water transport license\",\"questId\":3},{\"name\":\"Hello, nothing.\"}],\"text\":\"Hello, How can I assist you?\",\"sound\":\"cloud/npc/police/pd1.ogg\"},\"1\":{\"buttons\":[{\"name\":\"Start Test\",\"type\":\"take\",\"index\":\"0\"},{\"name\":\"Later\"}],\"text\":\"In order to obtain a driver's license, you must undergo a driving test, which incurs a fee of $800.\",\"sound\":\"\"},\"2\":{\"buttons\":[{\"name\":\"Start Test\",\"type\":\"take\",\"index\":\"1\"},{\"name\":\"Later\"}],\"text\":\"In order to obtain a air transport license, you must undergo a driving test, which incurs a fee of $2000.\",\"sound\":\"\"},\"3\":{\"buttons\":[{\"name\":\"Start Test\",\"type\":\"take\",\"index\":\"2\"},{\"name\":\"Later\"}],\"text\":\"In order to obtain a water transport license, you must undergo a driving test, which incurs a fee of $1500.\",\"sound\":\"\"}}");

